<?php namespace App\Http\Controllers;
use App\Models\Booking; use Illuminate\Http\Request;
class BookingController extends Controller { public function index(){return view('booking.index',['bookings'=>Booking::latest()->paginate(20)]);} public function show(Booking $booking){return view('booking.show',compact('booking'));} public function store(Request $r){$d=$r->validate(['tourism_package_id'=>'required|integer','visitor_name'=>'required','visitor_phone'=>'required','booking_date'=>'required|date','visitor_count'=>'required|integer|min:1','total_price'=>'required|numeric']);Booking::create($d+['status'=>'pending']);return back();} public function update(Request $r,Booking $booking){$booking->update($r->validate(['status'=>'required|in:pending,confirmed,cancelled,completed']));return back();} }
